export function canonicalize(raw: string): string | null {
  try {
    const decoded = raw === '@guide' ? 'public/guide' : decodeURIComponent(raw);
    if (posix.isAbsolute(decoded)) return null;
    return posix.normalize(decoded);
  } catch { return null; }
}

