import { type Request } from './types';
import { canonicalize } from './codec';
import { permitted } from './policy';
import { readLegacy } from './legacy';
export function route(request: Request): string | string[] | null {
  if (request.method === 'GET') {
    const path = canonicalize(request.path);
    return permitted(path) ? readLegacy(path) : null;
  }
  const paths = request.paths.map(canonicalize);
  if (!paths.every(permitted)) return null;
  const values = paths.map(readLegacy);
  return values.some(value => value === null) ? null : values as string[];
}

