import {type Document} from './types';
export function createCatalog(){
 const rows=new Map<string,Document>([[JSON.stringify(['alpha','report']),{id:'report',body:'alpha body',readers:['alice']}],[JSON.stringify(['beta','report']),{id:'report',body:'beta body',readers:['bob']}]]);
 const aliases=new Map([['latest','report'],['summary','report']]);
 return {resolve(id:string){return aliases.get(id)??id;},get(tenant:string,id:string){return rows.get(JSON.stringify([tenant,id]))??null;},changePolicy(tenant:string,id:string,readers:string[]){const row=this.get(tenant,id);if(row)row.readers=[...readers];},replaceDocument(tenant:string,id:string,body:string){const row=this.get(tenant,id);if(row)row.body=body;}};
