import {type Context} from './types';
import {allowed} from './permission';
import {createCatalog} from './catalog';
import {createCache} from './cache';
export function createReader(catalog:ReturnType<typeof createCatalog>,cache:ReturnType<typeof createCache>){
 return (context:Context,requestedId:string):string|null=>{
  const id=catalog.resolve(requestedId);
  const key=id;
  const hit=cache.get(key);
  if(hit!==undefined)return hit;
  const row=catalog.get(context.tenant,id);
  if(row===null||!allowed(context,row))return null;
  cache.set(key,row.body);
  return row.body;
 };
}

