import {createRegistry} from './registry';
import {execute} from './execute';
import {cleanup} from './cleanup';
import {type Work,type Result} from './types';
export function createRunner(now:()=>number,ttl:number){
 const registry=createRegistry();
 return {async run(key:string,work:Work):Promise<Result>{
  const lease=registry.claim(key,now(),ttl);
  if(lease===null)return 'busy';
  const result=await execute(work);
  if(result==='done')cleanup(registry,key,lease.token);
  return result;
 }};
}

