import {test,expect} from 'bun:test';
import {createRunner} from './index';
test('completion and retry',async()=>{
 let now=0;const api=createRunner(()=>now,10);let calls=0;
 expect(await api.run('a',async()=>{throw Error('work failed');})).toBe('failed');
 expect(await api.run('a',async()=>{calls++;})).toBe('done');
 expect(await api.run('a',async()=>{calls++;})).toBe('done');
 expect(calls).toBe(2);
});
test('ownership replacement and independent keys',async()=>{
 for(const fail of [false,true]){
  let now=0;const api=createRunner(()=>now,10);let releaseA!:()=>void,releaseB!:()=>void;
  const gateA=new Promise<void>(r=>releaseA=r),gateB=new Promise<void>(r=>releaseB=r);let calls=0;
  const a=api.run('a',async()=>{await gateA;if(fail)throw Error('old failure');});
  expect(await api.run('a',async()=>{calls++;})).toBe('busy');
  expect(calls).toBe(0);
  expect(await api.run('b',async()=>{})).toBe('done');
  now=10;
  const b=api.run('a',async()=>{await gateB;});
  releaseA();expect(await a).toBe(fail?'failed':'done');
  expect(await api.run('a',async()=>{calls++;})).toBe('busy');
  expect(calls).toBe(0);
  releaseB();expect(await b).toBe('done');
  expect(await api.run('a',async()=>{calls++;})).toBe('done');
  expect(calls).toBe(1);
 }
});
